const DAY_ORDER = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

function toMin(t) { const [h, m] = t.split(":").map(Number); return h * 60 + m; }
function ymd(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; }
function clsDate(c, which) { const [Y, Mo, D] = c.date.split("-").map(Number); const [h, m] = c[which].split(":").map(Number); return new Date(Y, Mo - 1, D, h, m); }
function fmtClock(d) { return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false }); }
function prettyDate(iso) { const [Y, M, D] = iso.split("-").map(Number); return new Date(Y, M - 1, D).toLocaleDateString([], { weekday: "long", day: "numeric", month: "short" }); }

const ALL_CODES = Object.keys(LEGEND);

export default function App() {
  const [now, setNow] = useState(new Date());
  const [section, setSection] = useState("A");
  const [view, setView] = useState("today");
  const [weekOffset, setWeekOffset] = useState(0);
  const [picker, setPicker] = useState(false);
  const [mine, setMine] = useState(() => new Set(ALL_CODES));
  const [syncedAt] = useState(new Date());

  useEffect(() => { const t = setInterval(() => setNow(new Date()), 20000); return () => clearInterval(t); }, []);

  // visible = my class entries for this section (+Single), plus all breaks/holidays/exams
  const visible = useMemo(() => {
    const seen = new Set();
    return CLASSES.filter((c) => {
      if (c.type === "class") return mine.has(c.code) && (c.section === section || c.section === "Single");
      const key = c.date + c.slot + c.name;
      if (seen.has(key)) return false; seen.add(key); return true;
    });
  }, [section, mine]);

  const todayISO = ymd(now);
  const todayList = useMemo(
    () => visible.filter((c) => c.date === todayISO).sort((a, b) => toMin(a.start) - toMin(b.start)),
    [visible, todayISO]
  );

  const { current, next } = useMemo(() => {
    const teach = visible.filter((c) => c.type === "class" || c.type === "exam")
      .map((c) => ({ ...c, s: clsDate(c, "start"), e: clsDate(c, "end") }))
      .sort((a, b) => a.s - b.s);
    return {
      current: teach.find((c) => c.s <= now && now < c.e) || null,
      next: teach.find((c) => c.s > now) || null,
    };
  }, [visible, now]);

  const syncedAgo = Math.max(0, Math.round((now - syncedAt) / 60000));

  return (
    <div className="app">
      <style>{CSS}</style>

      <header className="bar">
        <div className="brand">
          <div className="logo">αβ</div>
          <div>
            <div className="brand-name">Term Timetable</div>
            <div className="brand-sub">IIM Sambalpur · 15 Jun – 29 Aug</div>
          </div>
        </div>
        <div className="bar-right">
          <div className="seg" role="group" aria-label="Section">
            {["A", "B"].map((s) => (
              <button key={s} className={`seg-b ${section === s ? "on" : ""}`} onClick={() => setSection(s)}>Sec {s}</button>
            ))}
          </div>
          <button className="sync" onClick={() => setNow(new Date())} aria-label="Sync now"><RefreshCw size={15} /></button>
        </div>
      </header>

      <div className="livebar">
        <span className="live"><span className="pulse" /> Live · synced {syncedAgo === 0 ? "just now" : `${syncedAgo}m ago`}</span>
        <button className={`mybtn ${mine.size < ALL_CODES.length ? "active" : ""}`} onClick={() => setPicker((p) => !p)}>
          <Filter size={13} /> My courses · {mine.size}/{ALL_CODES.length}
        </button>
      </div>

      {picker && (
        <div className="picker">
          <div className="picker-head">
            <span>Show only the courses you're enrolled in</span>
            <div className="picker-acts">
              <button onClick={() => setMine(new Set(ALL_CODES))}>All</button>
              <button onClick={() => setMine(new Set())}>None</button>
            </div>
          </div>
          <div className="chips">
            {ALL_CODES.map((code) => (
              <button key={code} className={`chip ${mine.has(code) ? "on" : ""}`}
                onClick={() => setMine((prev) => { const n = new Set(prev); n.has(code) ? n.delete(code) : n.add(code); return n; })}>
                <span className="chip-code">{code}</span> {LEGEND[code].name}
              </button>
            ))}
          </div>
        </div>
      )}

      <nav className="tabs">
        <button className={`tab ${view === "today" ? "on" : ""}`} onClick={() => setView("today")}><Clock size={15} /> Today</button>
        <button className={`tab ${view === "week" ? "on" : ""}`} onClick={() => setView("week")}><Calendar size={15} /> Week</button>
        <div className="today-date">{prettyDate(todayISO)}</div>
      </nav>

      <Hero current={current} next={next} now={now} todayISO={todayISO} />

      {view === "today"
        ? <Timeline list={todayList} current={current} now={now} />
        : <WeekAgenda visible={visible} now={now} offset={weekOffset} setOffset={setWeekOffset} todayISO={todayISO} />}

      <footer className="foot">Snapshot of your sheet · connect it live to enable change alerts</footer>
    </div>
  );
}

function TypeBadge({ type }) {
  if (type === "holiday") return <span className="tb holiday">Holiday</span>;
  if (type === "exam") return <span className="tb exam">Exam / Admin</span>;
  if (type === "break") return <span className="tb break">Break</span>;
  return null;
}

function Hero({ current, next, now, todayISO }) {
  if (current) {
    const s = clsDate(current, "start"), e = clsDate(current, "end");
    const done = Math.min(1, Math.max(0, (now - s) / (e - s)));
    const left = Math.max(0, Math.round((e - now) / 60000));
    return (
      <section className="hero">
        <div className="hero-tag in"><span className="dot" /> In session{current.session ? ` · ${current.code} ${current.session}` : ""}</div>
        <h1 className="hero-course">{current.name}</h1>
        <div className="hero-meta">
          <span className="t">{current.start}<span className="dash">–</span>{current.end}</span>
          {current.room && <><span className="sep">·</span><span className="r"><MapPin size={14} /> {current.room}</span></>}
          {current.faculty && <><span className="sep">·</span><span className="f">{current.faculty}</span></>}
        </div>
        <div className="prog"><div className="prog-fill" style={{ width: `${done * 100}%` }} /></div>
        <div className="prog-label">{left} min left</div>
        {next && <UpNext c={next} now={now} />}
      </section>
    );
  }
  if (next) {
    const s = clsDate(next, "start");
    const sameDay = next.date === todayISO;
    const mins = Math.round((s - now) / 60000);
    return (
      <section className="hero">
        <div className="hero-tag next"><span className="dot amber" /> Up next{next.session ? ` · ${next.code} ${next.session}` : ""}</div>
        <h1 className="hero-course">{next.name}</h1>
        <div className="hero-meta">
          <span className="t">{next.start}</span>
          {next.room && <><span className="sep">·</span><span className="r"><MapPin size={14} /> {next.room}</span></>}
          {next.faculty && <><span className="sep">·</span><span className="f">{next.faculty}</span></>}
        </div>
        <div className="hero-when">{sameDay ? (mins <= 90 ? `Starts in ${mins} min` : "Later today") : prettyDate(next.date)}</div>
      </section>
    );
  }
  return (
    <section className="hero">
      <div className="hero-tag done"><span className="dot" /> All clear</div>
      <h1 className="hero-course">Nothing scheduled</h1>
      <div className="hero-when">No upcoming sessions in your selected courses.</div>
    </section>
  );
}

function UpNext({ c, now }) {
  return (
    <div className="upnext">
      <span className="up-label">Then</span>
      <span className="up-t">{c.start}</span>
      <span className="up-c">{c.name}</span>
      {c.room && <span className="up-r">{c.room}</span>}
    </div>
  );
}

function Timeline({ list, current, now }) {
  if (!list.length)
    return <section className="panel"><div className="panel-head"><h2>Today</h2></div><div className="empty">No sessions today for your courses. Check the week view.</div></section>;
  const nowMin = now.getHours() * 60 + now.getMinutes();
  return (
    <section className="panel">
      <div className="panel-head"><h2>Today</h2><span className="count">{list.filter(c => c.type === "class").length} classes</span></div>
      <ol className="rail">
        {list.map((c, i) => {
          const isCur = current && current.date === c.date && current.start === c.start && current.name === c.name;
          const showNow = !isCur && nowMin < toMin(c.start) && (i === 0 || nowMin >= toMin(list[i - 1].end));
          return (
            <React.Fragment key={i}>
              {showNow && <li className="nowline"><span className="nowdot" /><span className="nowtime">{fmtClock(now)}</span><span className="nowrule" /></li>}
              <li className={`row ${isCur ? "cur" : ""} ${c.type !== "class" ? "soft" : ""}`}>
                <div className="row-time"><span className="rt-start">{c.start}</span><span className="rt-end">{c.end}</span></div>
                <div className="row-body">
                  <div className="row-course">{c.name} {c.session && <span className="ses">{c.code} {c.session}</span>}</div>
                  <div className="row-meta">
                    {c.type === "class"
                      ? <>{c.room && <><MapPin size={13} /> {c.room}</>}{c.faculty && <> · {c.faculty}</>}{c.section === "Single" && <span className="single-tag">all</span>}</>
                      : <TypeBadge type={c.type} />}
                  </div>
                </div>
                {isCur && <span className="row-flag">now</span>}
              </li>
            </React.Fragment>
          );
        })}
      </ol>
    </section>
  );
}

function WeekAgenda({ visible, now, offset, setOffset, todayISO }) {
  const monday = new Date(now); const dow = (monday.getDay() + 6) % 7;
  monday.setDate(monday.getDate() - dow + offset * 7); monday.setHours(0, 0, 0, 0);
  const days = [...Array(7)].map((_, i) => { const d = new Date(monday); d.setDate(monday.getDate() + i); return d; });
  const label = `${monday.toLocaleDateString([], { day: "numeric", month: "short" })} – ${days[6].toLocaleDateString([], { day: "numeric", month: "short" })}`;
  return (
    <section className="panel">
      <div className="weeknav">
        <button onClick={() => setOffset(offset - 1)} aria-label="Previous week"><ChevronLeft size={18} /></button>
        <div className="weeknav-mid"><span className="wk-range">{label}</span>{offset !== 0 && <button className="wk-today" onClick={() => setOffset(0)}>This week</button>}</div>
        <button onClick={() => setOffset(offset + 1)} aria-label="Next week"><ChevronRight size={18} /></button>
      </div>
      {days.map((d) => {
        const iso = ymd(d);
        const items = visible.filter((c) => c.date === iso).sort((a, b) => toMin(a.start) - toMin(b.start));
        return (
          <div key={iso} className={`agday ${iso === todayISO ? "agtoday" : ""}`}>
            <div className="agday-h"><span className="agday-dow">{d.toLocaleDateString([], { weekday: "short" })}</span><span className="agday-num">{d.getDate()}</span>{iso === todayISO && <span className="agday-today">Today</span>}</div>
            <div className="agday-body">
              {items.length === 0 ? <span className="agday-free">—</span> : items.map((c, i) => (
                <div key={i} className={`ag ${c.type !== "class" ? "soft" : ""}`}>
                  <span className="ag-t">{c.start}</span>
                  <span className="ag-c">{c.type === "class" ? c.name : c.name}{c.session && <span className="ses">{c.code} {c.session}</span>}</span>
                  {c.type === "class" && c.room && <span className="ag-r">{c.room}</span>}
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </section>
  );
}
